import { R, X, lesson, mcq, numeric, short } from './helpers';
import type { Lesson } from '@/lib/types';

/**
 * HUMANOID.
 *
 * The HUMANOID track: bipedal, floating-base robots - the hardest class of
 * machine in this curriculum, and the one with the largest gap between what a
 * video shows and what a hobbyist can build. Every lesson carries that honesty:
 * the physics is taught properly, the difficulty is stated numerically, and the
 * achievable path (a small biped, then a subsystem, then research) is explicit.
 *
 * Order: why humanoids are hard -> static stability (CoM, support polygon, ZMP)
 * -> floating-base dynamics and momentum -> balance control and the capture
 * point -> walking and foot placement -> whole-body control -> actuator and
 * thermal reality -> building a small humanoid honestly.
 */
